// Voices are ElevenLabs library voices; any voice id from GET /v1/voices works.
const VOICES = {
  'George (British, warm storyteller)': 'JBFqnCBsd6RMkjVDRZzb',
  'Sarah (American, confident)': 'EXAVITQu4vr4xnSDxMaL',
  'Alice (British, clear educator)': 'Xb7hH8MSUJpSbSDYk0k2',
  'Brian (American, deep and calm)': 'nPczCjzI2devNBz1zQrb',
  'Daniel (British, broadcaster)': 'onwK4e9ZLuTAKqWW03F9',
  'Jessica (American, bright and conversational)': 'cgSgspJ2msm6clMCkdW9',
};
const WORDS = { 'Short (about 1 minute)': 150, 'Medium (about 3 minutes)': 420, 'Long (about 5 minutes)': 700 };

const form = $('Article form').first().json;
let text = (form['Or paste the text'] || '').trim();

if (!text && $('Fetch article page').isExecuted) {
  let html = String($('Fetch article page').first().json.data || '');
  const article = html.match(/<article[\s\S]*?<\/article>/i);
  if (article) html = article[0];
  text = html
    .replace(/<(script|style|noscript|svg|nav|header|footer|aside|form)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<\/(p|h[1-6]|li|div|br)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim();
}

if (text.length < 200) {
  throw new Error('Not enough article text. Paste the text into the form instead of the URL.');
}

return [{ json: {
  article: text.slice(0, 40000),
  voice_id: VOICES[form['Voice']] ?? VOICES['George (British, warm storyteller)'],
  style: form['Style'],
  words: WORDS[form['Length']] ?? 420,
} }];

