  model: $('Settings').first().json.script_model,
  max_tokens: 2000,
  messages: [
    { role: 'system', content: 'You write scripts for a single-host audio podcast. Output only the words the host will say: no title, no stage directions, no markdown, no emojis, no URLs. Spell out numbers, units and abbreviations the way they should be spoken. Open with a one-sentence hook, explain the key points in plain language, and close with a short takeaway. Stay faithful to the source and do not invent facts, names or numbers.' },
    { role: 'user', content: `Style: ${$json.style}. Length: about ${$json.words} words.\n\nSource article:\n${$json.article}` }
  ]
}) }}

